head.script:
scwin.objMainJSON = [
	{"id": "1", "no": 1},
	{"id": "2", "no": 2},
];

scwin.objSubJSON = [
	{"id": "1", "no": 1, "new": "N", "amt": 200000},
	{"id": "2", "no": 1, "new": "N", "amt": 200000},
	{"id": "3", "no": 1, "new": "N", "amt": 200000},
	{"id": "4", "no": 2, "new": "N", "amt": 200000},
	{"id": "5", "no": 2, "new": "N", "amt": 200000},
	{"id": "6", "no": 2, "new": "N", "amt": 200000},
	{"id": "7", "no": 2, "new": "Y", "amt": 300000},
	{"id": "8", "no": 2, "new": "Y", "amt": 300000},
	{"id": "9", "no": 2, "new": "Y", "amt": 300000},
	{"id": "10", "no": 2, "new": "Y", "amt": 300000},
	{"id": "11", "no": 2, "new": "Y", "amt": 300000},
];

scwin.onpageload = function() {
	dsMainList.setJSON(scwin.objMainJSON);
	dsSubList.setJSON(scwin.objSubJSON);
};

// 그리드 inputType getter : new=Y 면 checkbox, 아니면 text(readOnly)
scwin.fnGetType = function(info) {
	let objReturnInfo;
	switch (info.colID) {
		case "chk" :
			let sInputType, bReadOnly;
			const sNew = dsSubList.getCellData(info.rowIndex, "new");
			if (sNew != "Y") {
				sInputType = "text";
				bReadOnly = true;
			}
			else {
				sInputType = "checkbox";
				bReadOnly = false;
			}
			objReturnInfo = {
				id : "dynamic_" + sInputType + "_" + info.rowIndex + "_" + info.colIndex,
				inputType : sInputType,
				options : {
					readOnly: bReadOnly
				},
			};
			break;
		default:
			break;
	}
	return objReturnInfo;
};

scwin.dsMainList_onrowpositionchange = function(info) {
	const nRow = dsMainList.getRowPosition();
	dsSubList.clearFilter();
	dsSubList.setColumnFilter({
		type: "row",
		colIndex: "no",
		key: dsMainList.getCellData(nRow, "no"),
		condition: "and",
		exactMatch: true,
	});
};
